import pandas as pd

def check_pesel(pesel_str):
    if len(pesel_str) != 11:
        return False
    weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3]
    checksum = sum(int(pesel_str[i]) * weights[i] for i in range(10))
    checksum = (10 - (checksum % 10)) % 10
    return checksum == int(pesel_str[10])

