import pandas as pd
import ast
import datetime
import math

def get_levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return get_levenshtein_distance(s2, s1)
    if len(s2) == 0:
        return len(s1)
    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row
    return previous_row[-1]

def answer() -> dict[str, list[int]]:
    # Load data
    emp = pd.read_csv('/app/dataset/employees.csv')
    emp['PESEL'] = emp['PESEL'].astype(str).str.zfill(11)
    rates = dict(zip(emp['PESEL'], emp['hourly_rate']))

    tasks_df = pd.read_csv('/app/dataset/tasks.csv')
    task_pay = dict(zip(tasks_df['task_id'], tasks_df['pay_per_completion']))

    timesheet = pd.read_csv('/app/dataset/timesheet.csv')

    # 1. Correct dates
    timesheet['date'] = timesheet['date'].str.replace('04-31', '04-30').str.replace('06-31', '06-30')
    timesheet['date_obj'] = pd.to_datetime(timesheet['date']).dt.date

    # 2. Correct PESELs
    valid_pesels = set(emp['PESEL'])
    timesheet['employee_id'] = timesheet['employee_id'].astype(str).str.zfill(11)

    invalid_pesels = set(timesheet['employee_id']) - valid_pesels
    mapping = {}
    for inv in invalid_pesels:
        min_dist = 999
        closest = None
        for val in valid_pesels:
            dist = get_levenshtein_distance(inv, val)
            if dist < min_dist:
                min_dist = dist
                closest = val
        mapping[inv] = closest
    timesheet['employee_id'] = timesheet['employee_id'].replace(mapping)

    # 3. Parse tasks and fix brackets
    def parse_tasks(tasks_str):
        tasks_str = str(tasks_str).strip()
        if not tasks_str.startswith('['): tasks_str = '[' + tasks_str
        if not tasks_str.endswith(']'): tasks_str = tasks_str + ']'
        try:
            return ast.literal_eval(tasks_str)
        except:
            return []

    timesheet['task_list'] = timesheet['performed_tasks'].apply(parse_tasks)

    # 4. Drop duplicates
    timesheet = timesheet.drop_duplicates(subset=['date', 'hours_worked', 'performed_tasks', 'employee_id', 'facility_id'])

    # 5. Get billing month
    def get_first_tuesday(year, month):
        for day in range(1, 8):
            d = datetime.date(year, month, day)
            if d.weekday() == 1: # Tuesday
                return d
        return None

    def get_billing_month(date_obj):
        first_tue = get_first_tuesday(date_obj.year, date_obj.month)
        if date_obj < first_tue:
            if date_obj.month == 1:
                return (date_obj.year - 1, 12)
            else:
                return (date_obj.year, date_obj.month - 1)
        else:
            return (date_obj.year, date_obj.month)

    timesheet['billing_month'] = timesheet['date_obj'].apply(get_billing_month)

    # The billing months in dataset are (2025,3), (2025,4), (2025,5), (2025,6)
    billing_months = sorted(timesheet['billing_month'].unique())

    # Calculate salaries
    # We will accumulate salaries per employee per month
    salary_acc = {p: {m: 0.0 for m in billing_months} for p in valid_pesels}

    for index, row in timesheet.iterrows():
        emp_id = row['employee_id']
        b_month = row['billing_month']

        # Calculate row pay
        rate = rates.get(emp_id, 0)
        hw = row['hours_worked']
        # sum of bonuses for valid tasks
        bonus = sum(task_pay.get(t, 0) for t in row['task_list'])

        row_salary = hw * rate + bonus

        if emp_id in salary_acc and b_month in salary_acc[emp_id]:
            salary_acc[emp_id][b_month] += row_salary

    # Format the result
    result = {}
    for p in valid_pesels:
        salaries = []
        for m in billing_months:
            total = salary_acc[p][m]
            # Standard mathematical rounding: round to nearest integer, 0.5 rounds up
            rounded = int(math.floor(total + 0.5))
            salaries.append(rounded)
        result[p] = salaries

    return result

if __name__ == "__main__":
    import json
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

